import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { Tracer } from '../../src/index.ts';
import { SQLiteRepository } from '../../src/persistence/sqlite.ts';
import { canonical } from '../../src/core/evidence.ts';
const destination = 'projects/tracer/configuration-final-goal-audit.json'; assert.ok(!existsSync(destination));
const hash = value => createHash('sha256').update(value).digest('hex');
const artifact = path => ({ path, sha256: hash(readFileSync(path)) });
const objective = JSON.parse(readFileSync('output/configuration-change/final-goal-objective.json')).objective;
const paragraphs = objective.split('\n\n'); assert.equal(paragraphs.length, 9);
const audit = JSON.parse(readFileSync('projects/tracer/configuration-acceptance-audit.json'));
const complete = JSON.parse(readFileSync('projects/tracer/configuration-original-change-completed.json'));
const performed = JSON.parse(readFileSync('projects/tracer/configuration-full-verification-execution.json'));
const preserved = JSON.parse(readFileSync('projects/tracer/configuration-final-register-preservation.json'));
const original = JSON.parse(readFileSync('projects/tracer/configuration-change-original-case.json'));
const manifest = JSON.parse(readFileSync('projects/tracer/configuration-final-candidate-manifest.json'));
assert.equal(audit.status, 'all_original_criteria_verified_for_selected_local_scope'); assert.equal(audit.criteria.length, 12);
for (const c of audit.criteria) { assert.equal(c.status, 'verified_for_selected_local_software_scope'); for (const f of [...c.tests, ...c.reports]) assert.equal(artifact(f.path).sha256, f.sha256, f.path); }
for (const f of audit.additionalEvidence) assert.equal(artifact(f.path).sha256, f.sha256, f.path);
for (const f of manifest.files) { assert.equal(artifact(f.path).sha256, f.sha256, f.path); assert.equal(hash(execFileSync('git', ['show', 'HEAD:' + f.path], { maxBuffer: 16000000 })), f.sha256, f.path); }
for (const f of original.sourceStates) { assert.equal(hash(execFileSync('git', ['show', '99bfe3a:' + f.path])), f.sha256); assert.equal(hash(execFileSync('git', ['show', original.originalCommit + ':' + f.path])), f.sha256); }
assert.equal(execFileSync('git', ['show', original.originalCommit + ':src/application/configurations.ts'], { encoding: 'utf8' }).includes('captureExact'), false);
assert.equal(readFileSync('src/application/configurations.ts', 'utf8').includes('captureExact'), true);
const gateFiles = ['.fallowrc.json', 'eslint.config.js', 'playwright.config.ts', 'test/run-unit.ts', 'test/merge-coverage.ts'];
assert.equal(execFileSync('git', ['diff', original.originalCommit, 'HEAD', '--', ...gateFiles], { encoding: 'utf8' }), '');
assert.equal(artifact(audit.gates.log.path).sha256, audit.gates.log.sha256);
assert.match(readFileSync(audit.gates.log.path, 'utf8'), /ℹ pass 714/); assert.match(readFileSync(audit.gates.log.path, 'utf8'), /219 passed/);
assert.match(readFileSync('output/configuration-change/final-publication-format.log', 'utf8'), /All matched files use Prettier code style/);
assert.match(readFileSync('output/configuration-change/final-publication-build.log', 'utf8'), /✓ built/);
assert.equal(preserved.status, 'complete_selected_capability_preservation_pass'); assert.equal(preserved.finalNativeRevision, 189);
assert.equal(preserved.onlineBackup.sha256, artifact(preserved.onlineBackup.path).sha256);
const repository = new SQLiteRepository('projects/tracer/tracer.sqlite');
try {
  let io = 0; const t = new Tracer(repository, undefined, async () => { io++; throw Error('Completion audit cannot observe sources'); });
  const before = await t.exportProject(); assert.equal(before.projectRevision, 189); assert.equal(hash(canonical(before)), preserved.canonicalExportSha256);
  assert.deepEqual(JSON.parse(readFileSync('projects/tracer/project-export.json')), before);
  const verification = await t.verification.analyze(complete.verification.selection), assessment = await t.changeAssessments.analyze(complete.assessment.selection);
  assert.equal(verification.completion.state, 'verified'); assert.equal(verification.obligations.length, 12); assert.ok(verification.obligations.every(x => x.outcome === 'passed' && x.applicability === 'current'));
  assert.equal(verification.completion.receiptId, complete.verification.completion.receiptId); assert.equal(verification.view.scope.target.configurationId, complete.originalPair.afterId);
  assert.equal(assessment.completion.state, 'completed'); assert.equal(assessment.discovery, 'current'); assert.equal(assessment.obligations.length, 13); assert.ok(assessment.obligations.every(x => x.state === 'accounted' && x.openActions === 0));
  const byKey = key => before.current.entities.find(x => x.key === key);
  assert.equal(byKey('REQ-035').fields.deliveryStatus, 'implemented'); assert.equal(byKey('REQ-035').fields.verificationStatus, 'verified'); assert.equal(byKey('REQ-035').fields.validationStatus, 'not_validated'); assert.equal(byKey('WORK-027').fields.deliveryStatus, 'completed');
  for (const key of ['REQ-033', 'REQ-034']) { assert.equal(byKey(key).fields.verificationStatus, 'verified'); assert.equal(byKey(key).fields.validationStatus, 'not_validated'); }
  const spec = JSON.parse(readFileSync('projects/tracer/configuration-change-specification.json')); assert.deepEqual(audit.criteria.map(x => ({ id: x.id, expected: x.expected })), spec.acceptance.map(({ id, expected }) => ({ id, expected })));
  assert.equal(byKey('REQ-035').fields.acceptance, spec.acceptance.map(x => x.id + ': ' + x.expected).join(' '));
  const descriptions = [
    'All twelve original criteria have current passing controlled results for the exact after configuration. The actual original change assessment completes all thirteen candidates with zero actions; changed/unchanged/unknown scope and remaining excluded work remain explicit.',
    'The executed pre-implementation contract audit records five demonstrated gaps and reusable mechanisms. WORK-004 records completed investigation; selected REQ-035/VER-035/WORK-027 and the unchanged twelve-criterion specification existed before implementation. All seven genuine pre-edit source hashes match both initially named 99bfe3a and actual pre-edit d8f3865; the original source lacks captureExact. No prototype screen is used as a requirement source.',
    'Controlled capture selects stable exact native/link/content states plus schema/context and declared coverage; editable preparations remain separate. Legacy omitted topology/content stays unknown. Historical pins and independent resource observations remain readable through deletion/schema drift; hashes do not claim retained bytes.',
    'Deterministic comparison preserves full selected pins and native/field/topology/reference/content distinctions, unchanged context and unknown/comparability qualifications. Actual six changed/one unchanged original source states and final-source addition/removal/relink/JSON/legacy cases are retained. Read operations perform no observation IO; output/work limits refuse overflow.',
    'Shared selected-state readers, bounded declared-dependency discovery, pair-bound scope/policy, controlled judgments/actions and exact-target verification compose existing services. Actual discovery exhausted 48 one-row pages at native177 with unchanged export; final scope retains unknown excluded dependencies. Original outcomes/conclusions and independent B/C/B uses stay distinct from applicability, supersession and completed work.',
    'The shared default workspace and core/typed HTTP/client/CLI implement complete capture/compare/investigate/judge/verify/follow-through tasks. Production tests cover retained drafts, explicit stale adoption, failed reads, responsive context and uncertain response inspection without automatic replay. Actual restored original-intent recovery passes across interfaces without duplicate writes; shared services retain validation ownership and project descriptors own vocabulary.',
    'The original genuine capture-enhancement change has exact retained before/after, completed twelve-criterion verification and thirteen-candidate assessment. Its actually affected REQ-011 task preserves four activities including original failed/not_run and completes eighteen candidates. A configured research task genuinely computed means 12→13 from synthetic retained B/C/B CSVs and completes seven candidates. Final-source boundary/drift/reassessment/unknown cases pass. Fresh independent agent completed 8/8 unfamiliar task; material findings were addressed and actual-project follow-up limits retained separately from human validation.',
    'Final preservation compares native114, native187 and native189 live/restored state, retaining original identity/history/evidence/conclusions/outcomes and both previous application capabilities. Physical format11 is unchanged, so no migration was necessary. Canonical export, online/restored backup, exact state reads/recovery and all unchanged quality/regression gates pass. Owning architecture/usage/UX/checkpoint and register retain exact evidence, acceptance, independent validation status and limits. The current final audit covers every objective paragraph and every original criterion before goal completion.',
    'Delivery remains bounded to selected local software capability. No restoration/branching/release approval, authenticated-team/new-backend/cloud provider or regulatory/arbitrary-scale capability was introduced or claimed. Human/physical and other requirements retain independent unproven status.'
  ];
  const report = { date: '2026-10-28', status: 'full_original_objective_verified_for_selected_local_scope', objective, nativeRevision: 189, schemaVersion: 7, implementationCommit: performed.candidateCommit, implementationFiles: manifest.files.length, unchangedOriginalCriteria: audit.criteria.map(x => ({ id: x.id, expected: x.expected, status: 'verified', resolution: x.resolution })), objectiveChecks: paragraphs.map((requirement, i) => ({ id: 'OBJECTIVE-' + (i + 1), requirement, status: 'verified', evidence: descriptions[i] })), evidence: ['projects/tracer/configuration-change-audit.json', 'projects/tracer/configuration-change-specification.json', 'projects/tracer/configuration-change-original-case.json', 'projects/tracer/configuration-final-candidate-manifest.json', 'projects/tracer/configuration-full-verification-execution.json', 'projects/tracer/configuration-original-change-completed.json', 'projects/tracer/configuration-acceptance-audit.json', 'projects/tracer/configuration-final-register-preservation.json', 'projects/tracer/configuration-req011-execution.json', 'projects/tracer/configuration-research-follow-through.json', 'projects/tracer/configuration-application-walkthrough.json', 'projects/tracer/configuration-real-project-walkthrough.json'].map(artifact), documentation: ['docs/architecture.md', 'docs/developer-reference.md', 'docs/workspace-guide.md', 'docs/ux-plan.md', 'docs/checkpoint.md'].map(artifact), checks: { originalScopeUnchanged: true, originalNamedAndActualPreEditSourceStatesMatch: true, exactCommittedImplementationFiles: manifest.files.length, testGateConfigurationUnchanged: gateFiles.map(artifact), unitTests: 714, browserScenarios: 219, workbenchOriginalScreenshots: 18, fullGates: audit.gates.log, postDocumentationFormat: artifact('output/configuration-change/final-publication-format.log'), postDocumentationBuild: artifact('output/configuration-change/final-publication-build.log'), observerCalls: io, unchangedNativeExport: true }, savedProject: artifact('projects/tracer/project-export.json'), backup: preserved.onlineBackup, controlStates: { verification: verification.completion, assessment: assessment.completion, candidates: 13, openActions: 0, discovery: 'current', validation: 'not_validated' }, repositoryPublication: 'Implementation candidate is committed and all 781 fingerprints verified. Final documentation/evidence files are committed after this audit is saved; a post-commit check must confirm their recorded hashes and a clean worktree before marking the goal complete.', procedure: { path: 'output/configuration-change/audit-complete-goal.mjs', sha256: hash(readFileSync('output/configuration-change/audit-complete-goal.mjs')), source: readFileSync('output/configuration-change/audit-complete-goal.mjs', 'utf8') }, qualification: 'Complete original selected local software objective, not blanket product, standards, representative-human/physical, team/backend, provider or arbitrary-scale validation. Outside declared engineering scope remains unknown.' };
  assert.equal(io, 0); assert.deepEqual(await t.exportProject(), before);
  writeFileSync(destination, JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify({ objectiveParagraphs: paragraphs.length, originalCriteria: 12, status: report.status, candidateFiles: manifest.files.length, nativeRevision: 189 }));
} finally { repository.close(); }
